export function assertRetainedPreActorClosure(result,owner){assert.equal(result.code,1);assert.equal(result.signal,null);assertRetainedControllerEof(result);assert.equal(owner.protocolFailure,null,'ORIGINAL_NEGATIVE_PROTOCOL_FAILURE');assert.equal(owner.events.length,0);assert.equal(owner.actorStarted,false);}

class OriginalSession{
 constructor({argv,mode,publicKey,privateKey,session,scratch}){
  this.mode=mode;this.key=privateKey;this.publicKey=publicKey;this.session=session;this.sent=0;this.received=0;this.events=[];this.waiters=[];this.failed=null;this.closed=false;this.stdoutBytes=0;this.stderrBytes=0;this.stdoutEof=false;this.stderrEof=false;this.actorStarted=false;this.preActorFailure=null;this.pairAborted=null;this.originalController=null;
  const out=fs.openSync(path.join(scratch,mode+'.stdout'),'wx',0o600),err=fs.openSync(path.join(scratch,mode+'.stderr'),'wx',0o600);this.files=[out,err];
  this.child=spawn('docker',argv,{stdio:['pipe','pipe','pipe'],windowsHide:true});this.pid=this.child.pid;let pending=Buffer.alloc(0);
  this.protocolFailure=null;
  const rejectWaiters=error=>{this.failed??=error;for(const waiter of this.waiters.splice(0))waiter.reject(this.failed);};
  const fail=error=>{this.protocolFailure??=error;rejectWaiters(error);};
  this.child.stdin.on('error',fail);this.child.once('error',fail);
  this.child.stdout.on('data',chunk=>{this.stdoutBytes+=chunk.length;if(this.stdoutBytes<=48*1024*1024)fs.writeSync(out,chunk);else fail(Error('INQUIRY_ORIGINAL_OUTPUT_BOUND'));
   pending=Buffer.concat([pending,chunk]);if(pending.length>12*1024*1024){fail(Error('INQUIRY_ORIGINAL_FRAME_BOUND'));pending=Buffer.alloc(0);return;}
   for(let index;(index=pending.indexOf(10))>=0;){const line=pending.subarray(0,index).toString();pending=pending.subarray(index+1);try{assert.ok(line.startsWith(PREFIX));const frame=JSON.parse(line.slice(PREFIX.length));assert.equal(frame.format,FORMAT);assert.equal(frame.session,session);assert.equal(frame.role,'candidate');assert.equal(frame.sequence,++this.received);const raw=Buffer.from(frame.payload,'base64');assert.equal(raw.toString('base64'),frame.payload);assert.ok(raw.length<=8*1024*1024);const body=JSON.parse(raw);if(frame.event==='HELD'){this.failureFrame=body;throw Error('ORIGINAL_INQUIRY_CONTROLLER_HELD');}if(frame.event==='HELLO')this.originalController=body.originalController;if(frame.event==='ACTOR_STARTED')this.actorStarted=true;if(frame.event==='INQUIRY_PREACTOR_FAILED'){assert.ok(['old','current'].includes(mode));assert.equal(body.format,'sabalan-original-inquiry-preactor-failure/v1');assert.equal(body.mode,mode);assert.equal(body.nativeStartAttempted,false);assert.equal(body.childrenClosed,true);assert.equal(body.bothScopesInitial,true);assert.deepEqual(body.originalController,this.originalController);assert.equal(this.actorStarted,false);assert.equal(this.preActorFailure,null);this.preActorFailure=body;rejectWaiters(Error('ORIGINAL_INQUIRY_PREACTOR_FAILED'));continue;}const event={event:frame.event,body};const waiter=this.waiters[0];if(waiter){this.waiters.shift();assert.equal(event.event,waiter.expected);waiter.resolve(body);}else this.events.push(event);}catch(error){fail(error);}}
  });
  this.child.stderr.on('data',chunk=>{this.stderrBytes+=chunk.length;if(this.stderrBytes<=8*1024*1024)fs.writeSync(err,chunk);else fail(Error('INQUIRY_ORIGINAL_STDERR_BOUND'));});
  this.child.stdout.on('error',fail);this.child.stderr.on('error',fail);this.child.stdout.once('end',()=>{this.stdoutEof=true;if(pending.length)fail(Error('INQUIRY_ORIGINAL_TRAILING_FRAME_BYTES'));});this.child.stderr.once('end',()=>{this.stderrEof=true;});
  this.completion=new Promise(resolve=>this.child.once('close',(code,signal)=>{this.closed=true;for(const fd of this.files){fs.fsyncSync(fd);fs.closeSync(fd);}this.result={originalPid:this.pid,code,signal,stdoutBytes:this.stdoutBytes,stderrBytes:this.stderrBytes,stdoutEof:this.stdoutEof,stderrEof:this.stderrEof,trailingBytes:pending.length};if(this.waiters.length||pending.length||!this.stdoutEof||!this.stderrEof)fail(Error('INQUIRY_ORIGINAL_PREMATURE_CLOSE'));resolve(this.result);}));
 }
 async event(expected){if(this.failed)throw this.failed;if(this.events.length){const value=this.events.shift();assert.equal(value.event,expected);return value.body;}assert.equal(this.closed,false);return new Promise((resolve,reject)=>this.waiters.push({expected,resolve,reject}));}
 async send(command,body={}){assert.equal(this.closed,false);if(this.failed)throw this.failed;const payload=Buffer.from(JSON.stringify(body)).toString('base64'),sequence=++this.sent;assert.ok(payload.length<=10*1024*1024);const preimage=Buffer.from([FORMAT,this.session,'candidate',String(sequence),command,payload].join('\0'));const frame={format:FORMAT,session:this.session,role:'candidate',sequence,command,payload,signature:sign(null,preimage,this.key).toString('base64')};await new Promise((resolve,reject)=>this.child.stdin.write(PREFIX+JSON.stringify(frame)+'\n',error=>error?reject(error):resolve()));}
 async finishNegative(){assert.ok(this.preActorFailure||this.pairAborted);const result=await this.completion;assertRetainedPreActorClosure(result,this);return result;}
 async finish(){this.child.stdin.end();const result=await this.completion;assert.equal(result.code,0);assert.equal(result.signal,null);assertRetainedControllerEof(result);assert.equal(this.failed,null);assert.equal(this.events.length,0);return result;}
}

